@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @Spy
    private PriceCalculator priceCalculator = new PriceCalculator();

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldCalculateTotalWithDiscount() {
        Order order = new Order(1L, 100.0);
        when(orderRepository.findById(1L)).thenReturn(Optional.of(order));

        // Using doReturn for spy to avoid executing real method during stubbing
        doReturn(10.0).when(priceCalculator).calculateTax(anyDouble());

        double finalTotal = orderService.processOrder(1L);

        assertEquals(110.0, finalTotal);
        verify(orderRepository).findById(1L);
    }
}
